/* 校園美食地圖 — static frontend shared by every campus repo.
 * Data: data/places.json + data/config.json (generated by scripts/export_static.py).
 * Ranking / open-now / wheel logic mirrors the Python FoodMapService so results match.
 */
(() => {
  "use strict";

  const $ = (s) => document.querySelector(s);
  const $$ = (s) => [...document.querySelectorAll(s)];
  const TIER_LABEL = { low: "低", medium: "普通", high: "高" };
  const WHEEL_COLORS = ["#FFB4A2", "#B5E2D4", "#FFE08A", "#C7D7FF", "#F6C1E6", "#BDE7A9", "#FFD0A6", "#A9E2F3", "#E5D4FF", "#F9E79F"];
  const TOP_N_PINS = 10;
  const EARTH_R_KM = 6371.0;
  const RADIUS_PRESETS = [0.3, 0.5, 0.8, 1, 1.5, 2, 3, 5];

  let CFG = null;
  let PLACES = [];
  let rows = [];
  let selectedId = null;
  const state = { groups: new Set(), openOnly: false };

  // ---------- helpers ----------
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const toRad = (d) => (d * Math.PI) / 180;
  function haversineKm(lat1, lon1, lat2, lon2) {
    const p1 = toRad(lat1), p2 = toRad(lat2);
    const a = Math.sin((p2 - p1) / 2) ** 2 + Math.cos(p1) * Math.cos(p2) * Math.sin(toRad(lon2 - lon1) / 2) ** 2;
    return EARTH_R_KM * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(Math.max(0, 1 - a)));
  }
  const formatDistance = (m) => (m >= 1000 ? `${(m / 1000).toFixed(1)} km` : `${m} m`);
  const formatRadius = (km) => (km < 1 ? `${Math.round(km * 1000)} m` : `${km} km`);

  // ---------- opening hours (Asia/Taipei) — mirrors foodmap/opening_hours.py ----------
  const taipeiFmt = new Intl.DateTimeFormat("en-US", {
    timeZone: "Asia/Taipei", weekday: "short", year: "numeric", month: "numeric", day: "numeric",
    hour: "numeric", minute: "numeric", hourCycle: "h23",
  });
  const WEEKDAY = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  function taipeiNow() {
    const p = Object.fromEntries(taipeiFmt.formatToParts(new Date()).map((x) => [x.type, x.value]));
    return { y: +p.year, m: +p.month, d: +p.day, minutes: WEEKDAY[p.weekday] * 1440 + (+p.hour % 24) * 60 + +p.minute };
  }
  const ptMin = (pt) => (+pt.day || 0) * 1440 + (+pt.hour || 0) * 60 + (+pt.minute || 0);
  function openForPeriods(periods, now) {
    for (const per of periods) {
      if (!per || !per.open || typeof per.open !== "object") continue;
      const o = ptMin(per.open);
      if (!per.close || typeof per.close !== "object") { if (now >= o) return true; continue; }
      const c = ptMin(per.close);
      if (c <= o) { if (now >= o || now < c) return true; } else if (o <= now && now < c) return true;
    }
    return false;
  }
  function isOpenNow(p, now) {
    if (p.status === "CLOSED_PERMANENTLY" || p.status === "CLOSED_TEMPORARILY") return false;
    const h = p.hours;
    if (!h || !Array.isArray(h.periods)) return null;
    if (!h.periods.length) return false;
    if (Array.isArray(h.specialDays)) {
      const sp = h.specialDays.find((e) => e && e.date && +e.date.year === now.y && +e.date.month === now.m && +e.date.day === now.d);
      if (sp) {
        if (sp.closed === true) return false;
        if (Array.isArray(sp.exceptional_periods)) return openForPeriods(sp.exceptional_periods, now.minutes);
      }
    }
    return openForPeriods(h.periods, now.minutes);
  }
  const OPEN = { true: ["營業中", "open"], false: ["休息中", "closed"], null: ["時間未知", "unknown"] };
  const openBadge = (v) => { const [t, c] = OPEN[String(v)]; return `<span class="badge ${c}">${t}</span>`; };

  // ---------- ranking — mirrors FoodMapService.rank_nearby ----------
  function passesBudget(p, maxPriceLevel, maxSpend, includeUnknown) {
    if (maxPriceLevel == null && maxSpend == null) return true;
    if (p.avg_spend_ntd != null && maxSpend != null && p.avg_spend_ntd <= maxSpend) return true;
    if (p.price_level != null && maxPriceLevel != null && p.price_level <= maxPriceLevel) return true;
    return includeUnknown && p.avg_spend_ntd == null && p.price_level == null;
  }
  const SORTERS = {
    composite: (a, b) => b.composite - a.composite,
    huang: (a, b) => b.huang - a.huang || a.distKm - b.distKm,
    rating: (a, b) => b.bayes - a.bayes || a.distKm - b.distKm,
    distance: (a, b) => a.distKm - b.distKm,
  };
  function readState() {
    const budget = $("#f-budget").checked;
    return {
      lat: +$("#f-lat").value, lon: +$("#f-lon").value,
      radius: +$("#f-radius").value,
      minReviews: +$("#f-min-reviews").value || 0,
      groups: [...state.groups],
      maxPriceLevel: budget ? 1 : null,
      maxSpend: budget ? +$("#f-max-spend").value : null,
      includeUnknown: $("#f-unknown-price").checked,
      openOnly: state.openOnly,
      sort: $("#f-sort").value,
      limit: +$("#f-limit").value,
      q: $("#f-search").value.trim().toLowerCase(),
    };
  }
  function rank(st) {
    const now = taipeiNow();
    const out = [];
    for (const p of PLACES) {
      if (p.reviews < st.minReviews) continue;
      if (!passesBudget(p, st.maxPriceLevel, st.maxSpend, st.includeUnknown)) continue;
      if (st.groups.length && !p.groups.some((g) => st.groups.includes(g))) continue;
      if (st.q && !p.name.toLowerCase().includes(st.q) && !p.groups.some((g) => g.includes(st.q))) continue;
      const distKm = haversineKm(st.lat, st.lon, p.lat, p.lon);
      if (distKm > st.radius) continue;
      const open = isOpenNow(p, now);
      if (st.openOnly && open !== true) continue;
      out.push({ ...p, distKm, distText: formatDistance(Math.round(distKm * 1000)), open, composite: p.huang * Math.exp(-distKm / CFG.decay_km) });
    }
    out.sort(SORTERS[st.sort] || SORTERS.composite);
    return out.slice(0, st.limit);
  }

  // ---------- map ----------
  let map, dotLayer, pinLayer, centerMarker, radiusCircle;
  const markerById = new Map();
  function initMap() {
    const t = CFG.tiles || {};
    map = L.map("map", { preferCanvas: true, zoomControl: false }).setView(CFG.center, 15);
    L.control.zoom({ position: "topright" }).addTo(map);
    L.tileLayer(t.url || "https://wmts.nlsc.gov.tw/wmts/EMAP5/default/GoogleMapsCompatible/{z}/{y}/{x}", {
      maxZoom: t.max_zoom || 19,
      subdomains: t.subdomains || "abc",
      attribution: t.attribution || '&copy; <a href="https://maps.nlsc.gov.tw/">內政部國土測繪中心</a>',
    }).addTo(map);
    radiusCircle = L.circle(CFG.center, { radius: 500, color: "#e8590c", weight: 1.5, dashArray: "6 6", fillColor: "#e8590c", fillOpacity: 0.04, interactive: false }).addTo(map);
    dotLayer = L.layerGroup().addTo(map);
    pinLayer = L.layerGroup().addTo(map);
    centerMarker = L.marker(CFG.center, {
      draggable: true, zIndexOffset: 2000, keyboard: false,
      icon: L.divIcon({ className: "", html: '<div class="center-pin"></div>', iconSize: [20, 20], iconAnchor: [10, 10] }),
      title: "中心點（可拖曳）",
    }).addTo(map);
    centerMarker.on("dragend", () => {
      const { lat, lng } = centerMarker.getLatLng();
      setCenter(lat, lng, "已改用拖曳的位置");
    });
  }
  function popupHtml(r) {
    return `<div class="pop-name">${esc(r.name)}</div>
      <div><span class="star">★ ${r.rating.toFixed(1)}</span> <span class="muted">(${r.reviews.toLocaleString("zh-TW")})</span> · ${r.distText}</div>
      <div>${openBadge(r.open)}</div>
      <a class="pop-link" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Google Maps 導航 →</a>`;
  }
  function drawMap(st, fit) {
    dotLayer.clearLayers();
    pinLayer.clearLayers();
    markerById.clear();
    rows.forEach((r, i) => {
      const sel = r.id === selectedId;
      let m;
      if (i < TOP_N_PINS || sel) {
        m = L.marker([r.lat, r.lon], {
          zIndexOffset: sel ? 1500 : 1000 - i,
          icon: L.divIcon({ className: "", html: `<div class="num-pin${sel ? " sel" : ""}"><span>${i + 1}</span></div>`, iconSize: sel ? [34, 34] : [28, 28], iconAnchor: sel ? [17, 34] : [14, 28], popupAnchor: [0, -30] }),
          title: r.name,
        }).addTo(pinLayer);
      } else {
        m = L.circleMarker([r.lat, r.lon], { radius: 5.5, color: "#fff", weight: 1.5, fillColor: "#e8590c", fillOpacity: 0.55 }).addTo(dotLayer);
      }
      m.bindPopup(popupHtml(r), { closeButton: false, autoPanPadding: [40, 40] });
      m.on("click", () => selectRow(r.id, { fromMap: true }));
      markerById.set(r.id, m);
    });
    centerMarker.setLatLng([st.lat, st.lon]);
    radiusCircle.setLatLng([st.lat, st.lon]).setRadius(st.radius * 1000);
    if (fit) fitRadius(st);
  }
  function fitRadius(st) {
    st = st || readState();
    // Circle#getBounds is stale until redraw; compute from center + radius instead.
    map.fitBounds(L.latLng(st.lat, st.lon).toBounds(st.radius * 2000), { padding: [16, 16], maxZoom: 17 });
  }

  // ---------- list ----------
  function cardHtml(r, i) {
    const tags = r.groups.filter((g) => g !== CFG.food_group_other).map((g) => `<span class="tag">${esc(g.replace(/類$/, ""))}</span>`).join("");
    const sel = r.id === selectedId;
    return `<li class="rcard${i < TOP_N_PINS ? " top" : ""}${sel ? " selected" : ""}" data-id="${esc(r.id)}" tabindex="0" aria-expanded="${sel}">
      <span class="rank">${i + 1}</span>
      <h3 class="rname">${esc(r.name)}</h3>
      <div class="rscore"><b>${r.composite.toFixed(2)}</b><span>綜合</span></div>
      <div class="rmeta"><span><span class="star">★ ${r.rating.toFixed(1)}</span> (${r.reviews.toLocaleString("zh-TW")})</span><span>${r.distText}</span>${openBadge(r.open)}${r.spend !== "未提供" ? `<span>${esc(r.spend)}</span>` : ""}</div>
      ${tags ? `<div class="rtags">${tags}</div>` : ""}
      <div class="rdetail">
        <div class="stats">
          <div class="stat"><b>${r.huang.toFixed(2)}</b><span>黃氏星等</span></div>
          <div class="stat"><b>${r.bayes.toFixed(2)}</b><span>貝氏星等</span></div>
          <div class="stat"><b>${TIER_LABEL[r.tier] || r.tier}</b><span>星等分級</span></div>
        </div>
        <div class="ractions"><a class="btn btn-primary" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Google Maps 導航</a></div>
      </div>
    </li>`;
  }
  function drawList() {
    $("#results").innerHTML = rows.map(cardHtml).join("");
    $("#empty").hidden = rows.length > 0;
  }
  function selectRow(id, { fromMap = false } = {}) {
    selectedId = selectedId === id && !fromMap ? null : id;
    drawList();
    drawMap(readState(), false);
    const r = rows.find((x) => x.id === selectedId);
    if (!r) { map.closePopup(); return; }
    if (!fromMap) map.setView([r.lat, r.lon], Math.max(map.getZoom(), 16), { animate: true });
    const m = markerById.get(r.id);
    if (m) m.openPopup();
    const card = document.querySelector(`.rcard[data-id="${CSS.escape(r.id)}"]`);
    if (card) card.scrollIntoView({ block: "nearest", behavior: "smooth" });
  }

  // ---------- wheel — mirrors foodmap/wheel.py + streamlit_app._wheel_candidate_df ----------
  let wheelItems = [], wheelSig = null, rotation = 0, spinning = false;
  function wheelEligible(r) {
    if (CFG.wheel_excluded_name_keywords.some((k) => r.name.includes(k))) return false;
    return r.groups.length > 0 && !r.groups.some((g) => CFG.wheel_excluded_groups.includes(g));
  }
  function wheelCandidates(st) {
    let c = rows.filter((r) => r.open !== false && wheelEligible(r));
    if (st.groups.length) {
      const wg = new Set([...st.groups, CFG.food_group_other]);
      c = c.filter((r) => r.groups.some((g) => wg.has(g)));
    }
    c.sort((a, b) => b.composite - a.composite);
    const pins = new Set(CFG.wheel_pinned_ids || []);
    if (pins.size) {
      const pinned = c.filter((r) => pins.has(r.id));
      if (pinned.length) c = [...pinned, ...c.filter((r) => !pins.has(r.id))];
    }
    return c.slice(0, CFG.wheel_top_n);
  }
  function shortName(name, max) {
    const base = name.split(/[｜|（(\-–—]/)[0].trim() || name.trim();
    const chars = [...base];
    return chars.length <= max ? base : chars.slice(0, max - 1).join("") + "…";
  }
  const polar = (cx, cy, R, deg) => [cx + R * Math.cos(toRad(deg - 90)), cy + R * Math.sin(toRad(deg - 90))];
  function drawWheel(st) {
    if (spinning) return;
    const items = wheelCandidates(st);
    const sig = items.map((r) => `${r.id}:${r.composite.toFixed(2)}`).join("|");
    if (sig === wheelSig) return; // unchanged → keep the last result on screen
    wheelSig = sig;
    wheelItems = items;
    const n = items.length;
    $("#wheel-n").textContent = n;
    $("#wheel-spin").disabled = n === 0;
    $("#wheel-caption").textContent = n
      ? `從目前範圍內營業中（或時間未知）的正餐，取推薦前 ${n} 家，每家機率相同${st.groups.length ? "（已套用分類）" : ""}。`
      : "目前沒有可以抽的店，請放寬篩選條件。";
    const pins = new Set(CFG.wheel_pinned_ids || []);
    $("#wheel-legend").innerHTML = items.map((r, i) => `<li data-index="${i}"><span class="wl-no" style="background:${WHEEL_COLORS[i % WHEEL_COLORS.length]}">${i + 1}</span>${pins.has(r.id) ? '<span class="wl-pin" title="站長推薦">★</span>' : ""}<span class="wl-name" title="${esc(r.name)}">${esc(r.name)}</span><span class="muted">${r.distText}</span></li>`).join("");
    const rotor = $("#wheel-rotor");
    if (!n) { rotor.innerHTML = ""; resetResult(); return; }
    const cx = 200, cy = 200, R = 200, slice = 360 / n, large = slice > 180 ? 1 : 0;
    const fs = n > 32 ? 12 : n > 24 ? 14 : 17;
    let svg = "";
    for (let i = 0; i < n; i++) {
      const center = i * slice, color = WHEEL_COLORS[i % WHEEL_COLORS.length];
      if (n === 1) svg += `<circle cx="${cx}" cy="${cy}" r="${R}" fill="${color}"/>`;
      else {
        const [x1, y1] = polar(cx, cy, R, center - slice / 2), [x2, y2] = polar(cx, cy, R, center + slice / 2);
        svg += `<path d="M${cx},${cy} L${x1.toFixed(2)},${y1.toFixed(2)} A${R},${R} 0 ${large},1 ${x2.toFixed(2)},${y2.toFixed(2)} Z" fill="${color}" stroke="#fff" stroke-width="1"/>`;
      }
      if (n <= 16) {
        // Few slices: print the shop name radially so the wheel reads without the legend.
        const label = shortName(items[i].name, n <= 8 ? 7 : 6);
        const [tx, ty] = polar(cx, cy, R * 0.6, center);
        const rot = center - 90;
        svg += `<text x="${tx.toFixed(2)}" y="${ty.toFixed(2)}" transform="rotate(${rot.toFixed(2)} ${tx.toFixed(2)} ${ty.toFixed(2)})" text-anchor="middle" dominant-baseline="middle" class="wheel-name" font-size="${n <= 8 ? 17 : 14}">${esc(label)}</text>`;
      } else {
        const [tx, ty] = polar(cx, cy, R * (n > 24 ? 0.85 : 0.7), center);
        svg += `<text x="${tx.toFixed(2)}" y="${ty.toFixed(2)}" text-anchor="middle" dominant-baseline="middle" class="wheel-label" font-size="${fs}">${i + 1}</text>`;
      }
    }
    rotor.innerHTML = svg;
    resetWheel();
  }
  const rotMod = (r) => ((r % 360) + 360) % 360;
  const segmentAt = (rot, n) => { const s = 360 / n; return ((Math.floor((360 - rotMod(rot) + s / 2) / s) % n) + n) % n; };
  function resetResult() {
    $("#wheel-result").innerHTML = "<p>按中間的 <b>GO</b>，讓轉盤幫你決定。</p>";
    $$("#wheel-legend li").forEach((li) => li.classList.remove("active"));
  }
  function resetWheel() {
    const rotor = $("#wheel-rotor");
    rotation = 0;
    rotor.style.transition = "none";
    rotor.style.transform = "rotate(0deg)";
    requestAnimationFrame(() => { rotor.style.transition = ""; });
    resetResult();
  }
  function spin() {
    const n = wheelItems.length;
    if (spinning || !n) return;
    spinning = true;
    $("#wheel-spin").disabled = true;
    $("#wheel-result").innerHTML = "<p>轉轉轉…</p>";
    const slice = 360 / n;
    const winner = Math.floor(Math.random() * n);
    let delta = rotMod(360 - winner * slice) - rotMod(rotation);
    if (delta <= 0) delta += 360;
    rotation += (4 + Math.floor(Math.random() * 3)) * 360 + delta;
    $("#wheel-rotor").style.transform = `rotate(${rotation}deg)`;
    const dur = matchMedia("(prefers-reduced-motion: reduce)").matches ? 50 : 4300;
    setTimeout(() => {
      const idx = segmentAt(rotation, n), r = wheelItems[idx];
      $$("#wheel-legend li").forEach((li) => li.classList.toggle("active", +li.dataset.index === idx));
      $("#wheel-result").innerHTML = `<h3>#${idx + 1} ${esc(r.name)}</h3>
        <p><span class="star">★ ${r.rating.toFixed(1)}</span> (${r.reviews.toLocaleString("zh-TW")}) · ${r.distText} · ${openBadge(r.open)}</p>
        <a class="btn btn-primary" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Google Maps 導航</a>`;
      if (navigator.vibrate) navigator.vibrate(30);
      spinning = false;
      $("#wheel-spin").disabled = false;
    }, dur);
  }

  // ---------- render ----------
  let queued = false;
  function render({ fit = false } = {}) {
    const st = readState();
    if (!Number.isFinite(st.lat) || !Number.isFinite(st.lon)) return;
    rows = rank(st);
    if (selectedId && !rows.some((r) => r.id === selectedId)) selectedId = null;
    $("#result-count").innerHTML = `<strong>${rows.length}</strong> 家 · ${formatRadius(st.radius)} 內`;
    drawList();
    drawMap(st, fit);
    drawWheel(st);
    syncFilterDot(st);
    saveState(st);
  }
  function scheduleRender() {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => { queued = false; render(); });
  }
  function setCenter(lat, lon, msg) {
    $("#f-lat").value = lat.toFixed(6);
    $("#f-lon").value = lon.toFixed(6);
    $("#center-status").textContent = msg || "";
    render({ fit: true });
  }
  function syncFilterDot(st) {
    const moved = Math.abs(st.lat - CFG.center[0]) > 1e-6 || Math.abs(st.lon - CFG.center[1]) > 1e-6;
    $("#filter-dot").hidden = !(moved || st.minReviews > 0 || st.maxSpend != null || st.limit !== 300);
  }

  // ---------- persistence (per-viewer convenience only) ----------
  const storeKey = () => `foodmap:${CFG.counter_namespace || CFG.school}:v2`;
  function saveState(st) {
    try {
      localStorage.setItem(storeKey(), JSON.stringify({
        radius: st.radius, minReviews: st.minReviews, groups: st.groups, openOnly: st.openOnly,
        budget: $("#f-budget").checked, maxSpend: $("#f-max-spend").value, unknown: st.includeUnknown, sort: st.sort, limit: st.limit,
      }));
    } catch (_e) { /* storage unavailable */ }
  }
  function loadState() {
    try { return JSON.parse(localStorage.getItem(storeKey()) || "null"); } catch (_e) { return null; }
  }

  // ---------- chips ----------
  function buildChips() {
    const groups = CFG.food_group_sidebar.flatMap(([, gs]) => gs).concat([CFG.food_group_other]);
    $("#chips").innerHTML =
      '<button type="button" class="chip" data-quick="open" aria-pressed="false">營業中</button>' +
      '<button type="button" class="chip" data-quick="cheap" aria-pressed="false">平價</button>' +
      '<span class="chip-sep" aria-hidden="true"></span>' +
      groups.map((g) => `<button type="button" class="chip" data-group="${esc(g)}" aria-pressed="false">${esc(g.replace(/類$/, ""))}</button>`).join("");
    $("#chips").addEventListener("click", (e) => {
      const chip = e.target.closest(".chip");
      if (!chip) return;
      if (chip.dataset.quick === "open") state.openOnly = !state.openOnly;
      else if (chip.dataset.quick === "cheap") { $("#f-budget").checked = !$("#f-budget").checked; syncBudget(); }
      else {
        const g = chip.dataset.group;
        if (state.groups.has(g)) state.groups.delete(g); else state.groups.add(g);
      }
      syncChips();
      render();
    });
  }
  function syncChips() {
    $$("#chips .chip").forEach((c) => {
      const on = c.dataset.quick === "open" ? state.openOnly
        : c.dataset.quick === "cheap" ? $("#f-budget").checked
        : state.groups.has(c.dataset.group);
      c.setAttribute("aria-pressed", String(on));
    });
  }
  function syncBudget() {
    $$(".budget-only").forEach((el) => { el.hidden = !$("#f-budget").checked; });
    $("#o-max-spend").textContent = `$${$("#f-max-spend").value}`;
  }

  // ---------- views ----------
  function setView(v) {
    $("#app").dataset.view = v;
    $$(".view-tab").forEach((t) => t.setAttribute("aria-selected", String(t.dataset.view === v)));
    if (v === "map") setTimeout(() => map.invalidateSize(), 0);
    try { history.replaceState(null, "", v === "map" ? location.pathname : `#${v}`); } catch (_e) { /* ignore */ }
  }

  async function geocode() {
    const q = $("#f-place").value.trim();
    if (!q) return;
    const btn = $("#btn-geocode");
    btn.disabled = true;
    $("#center-status").textContent = "查詢中…";
    try {
      const url = `https://nominatim.openstreetmap.org/search?${new URLSearchParams({ q, format: "json", limit: "1", countrycodes: "tw", "accept-language": "zh-TW" })}`;
      const data = await (await fetch(url, { headers: { Accept: "application/json" } })).json();
      if (!Array.isArray(data) || !data.length) throw new Error("not found");
      setCenter(+data[0].lat, +data[0].lon, `已設定：${q}`);
    } catch (_e) {
      $("#center-status").textContent = "找不到這個地點，換個關鍵字試試（可加縣市名）。";
    } finally { btn.disabled = false; }
  }
  function locate() {
    if (!navigator.geolocation) { $("#center-status").textContent = "這個瀏覽器不支援定位。"; return; }
    $("#center-status").textContent = "定位中…";
    navigator.geolocation.getCurrentPosition(
      (pos) => setCenter(pos.coords.latitude, pos.coords.longitude, "已改用你目前的位置"),
      () => { $("#center-status").textContent = "無法取得位置（可能沒有授權）。"; },
      { enableHighAccuracy: true, timeout: 10000 },
    );
  }
  function resetAll() {
    state.groups.clear();
    state.openOnly = false;
    $("#f-search").value = "";
    $("#f-budget").checked = false;
    $("#f-max-spend").value = 100;
    $("#f-unknown-price").checked = true;
    $("#f-min-reviews").value = "0";
    $("#f-limit").value = "300";
    $("#f-radius").value = String(CFG.default_radius_km);
    $("#f-sort").value = "composite";
    $("#f-lat").value = CFG.center[0].toFixed(6);
    $("#f-lon").value = CFG.center[1].toFixed(6);
    $("#center-status").textContent = "";
    syncBudget();
    syncChips();
    render({ fit: true });
  }

  function wire() {
    $("#f-search").addEventListener("input", scheduleRender);
    $("#f-radius").addEventListener("change", () => render({ fit: true }));
    $("#f-sort").addEventListener("change", () => render());
    ["#f-min-reviews", "#f-limit", "#f-unknown-price"].forEach((s) => $(s).addEventListener("change", () => render()));
    $("#f-budget").addEventListener("change", () => { syncBudget(); syncChips(); render(); });
    $("#f-max-spend").addEventListener("input", () => { syncBudget(); scheduleRender(); });
    ["#f-lat", "#f-lon"].forEach((s) => $(s).addEventListener("change", () => render({ fit: true })));
    $("#btn-geocode").addEventListener("click", geocode);
    $("#f-place").addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); geocode(); } });
    $("#btn-locate").addEventListener("click", locate);
    $("#btn-reset-center").addEventListener("click", () => setCenter(CFG.center[0], CFG.center[1], `已回到${CFG.campus_name}`));
    $("#btn-clear-all").addEventListener("click", resetAll);
    $("#btn-reset-filters").addEventListener("click", resetAll);
    $("#btn-recenter").addEventListener("click", () => fitRadius());
    $("#btn-filters").addEventListener("click", () => {
      const d = $("#filters");
      if (typeof d.showModal === "function") d.showModal(); else d.setAttribute("open", "");
    });
    $("#filters").addEventListener("click", (e) => { if (e.target === e.currentTarget) e.currentTarget.close(); });

    const results = $("#results");
    results.addEventListener("click", (e) => {
      if (e.target.closest("a")) return;
      const li = e.target.closest(".rcard");
      if (li) selectRow(li.dataset.id);
    });
    results.addEventListener("keydown", (e) => {
      const li = e.target.closest(".rcard");
      if (!li) return;
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); selectRow(li.dataset.id); }
      if (e.key === "ArrowDown" || e.key === "ArrowUp") {
        e.preventDefault();
        const next = e.key === "ArrowDown" ? li.nextElementSibling : li.previousElementSibling;
        if (next) next.focus();
      }
    });

    $$(".view-tab").forEach((t) => t.addEventListener("click", () => setView(t.dataset.view)));
    $("#wheel-spin").addEventListener("click", spin);
    $("#wheel-reset").addEventListener("click", () => { if (!spinning) resetWheel(); });
  }

  function visitCounter() {
    const ns = CFG.counter_namespace, label = $("#visits");
    if (!ns) { label.remove(); return; }
    const base = `https://api.counterapi.dev/v1/${encodeURIComponent(ns)}/visits/`;
    const key = `${ns}_visit_counted`;
    let counted = false;
    try { counted = sessionStorage.getItem(key) === "1"; } catch (_e) { /* ignore */ }
    fetch(counted ? base : `${base}up`)
      .then((r) => { if (!r.ok) throw new Error(); return r.json(); })
      .then((p) => {
        const v = +(p && p.count);
        if (!Number.isFinite(v) || v < 0) throw new Error();
        try { sessionStorage.setItem(key, "1"); } catch (_e) { /* ignore */ }
        label.textContent = `累計瀏覽 ${v.toLocaleString("zh-TW")} 人次`;
      })
      .catch(() => { label.remove(); });
  }

  async function boot() {
    try {
      // no-cache: always revalidate so a redeploy (e.g. new basemap) shows up right away.
      const [cfg, places] = await Promise.all([
        fetch("data/config.json", { cache: "no-cache" }).then((r) => r.json()),
        fetch("data/places.json", { cache: "no-cache" }).then((r) => r.json()),
      ]);
      CFG = cfg;
      PLACES = places;
    } catch (_e) {
      $("#site-sub").textContent = "資料載入失敗，請重新整理。";
      return;
    }
    document.title = CFG.title;
    $("#site-title").textContent = CFG.title;
    $("#site-title-short").textContent = `${CFG.school}美食地圖`;
    $("#site-sub").textContent = `${CFG.campus_name}周邊 · ${PLACES.length} 家店`;
    $("#author").textContent = CFG.author_notice;
    if (CFG.repo_url) $("#repo-link").innerHTML = `<a href="${esc(CFG.repo_url)}" target="_blank" rel="noopener noreferrer">GitHub</a>`;
    $("#btn-reset-center").textContent = `回到${CFG.campus_name}`;

    const maxR = CFG.max_radius_km || 5;
    const presets = [...new Set([...RADIUS_PRESETS, CFG.default_radius_km])].filter((r) => r <= maxR).sort((a, b) => a - b);
    $("#f-radius").innerHTML = presets.map((r) => `<option value="${r}">${formatRadius(r)}</option>`).join("");

    const saved = loadState();
    $("#f-lat").value = CFG.center[0].toFixed(6);
    $("#f-lon").value = CFG.center[1].toFixed(6);
    $("#f-radius").value = String(saved && presets.includes(saved.radius) ? saved.radius : CFG.default_radius_km);
    if (saved) {
      (saved.groups || []).forEach((g) => state.groups.add(g));
      state.openOnly = !!saved.openOnly;
      $("#f-min-reviews").value = String(saved.minReviews || 0);
      $("#f-budget").checked = !!saved.budget;
      $("#f-max-spend").value = saved.maxSpend || 100;
      $("#f-unknown-price").checked = saved.unknown ?? true;
      if (SORTERS[saved.sort]) $("#f-sort").value = saved.sort;
      if ([20, 50, 100, 300].includes(saved.limit)) $("#f-limit").value = String(saved.limit);
    } else {
      $("#f-limit").value = "300";
    }
    if (!$("#f-min-reviews").value) $("#f-min-reviews").value = "0";
    buildChips();
    syncBudget();
    syncChips();
    initMap();
    wire();
    const hashView = location.hash.slice(1);
    if (hashView === "wheel" || hashView === "guide") setView(hashView);
    render({ fit: true });
    visitCounter();
    setInterval(() => { if (!spinning) render(); }, 5 * 60 * 1000); // keep open/closed badges fresh

    if ("serviceWorker" in navigator && location.protocol === "https:") {
      navigator.serviceWorker.register("sw.js").catch(() => {});
    }
  }

  boot();
})();
